    [4743]={name="Pulsating Crystalline Shard",quality=2,ilvl=50,reqLevel=30,sourceType="quest_reward",instructions="Reward from the quest 'Summoning the Princess'. Starts with Theldurin the Lost in Arathi Highlands. Objective: Go to the Shards of Myzrael, summon her and defeat her.Gather her Eldritch Shackles and bind them to the Shards of Myzrael.",zone="Arathi Highlands",questName="Summoning the Princess",lore="You must defeat Myzrael before she grows in strength. If you do not, then once she has gathered enough power she will challenge her captors!"},
    [4744]={name="Arcane Runed Bracers",quality=2,ilvl=39,reqLevel=30,sourceType="quest_reward",instructions="Reward from the quest 'Wanted! Marez Cowl'.",zone="Arathi Highlands",questName="Wanted!  Marez Cowl",lore="A bounty has been placed on the head of Marez Cowl, a high-level advisor and operative of the Syndicate. She was last seen within the Syndicate controlled territory of Stromgarde."},
    [4746]={name="Doomsayer's Robe",quality=2,ilvl=42,reqLevel=30,sourceType="quest_reward",instructions="Reward from the quest 'Solution to Doom'. Starts with Theldurin the Lost in Badlands. Objective: Bring the Tablet of Ryun'eh to Theldurin the Lost.",zone="Uldaman",questName="Solution to Doom",lore="Oh my! Oh my! There is a doom approaching. Mark me! A doom! No, I cannot speak of it...cannot utter their names or they may hear me! But if we learn, yes, if we learn more of them...then maybe we can learn how to foil them!"},
    [4767]={name="Coppercloth Gloves",quality=2,ilvl=15,reqLevel=10,sourceType="world_drop",instructions="Drops from Dalaran Miner.",zone="Silverpine Forest",npc="Dalaran Miner",zoneOpen=true},
