    [6266]={name="Disciple's Vest",quality=2,ilvl=13,reqLevel=8,sourceType="world_drop",instructions="World drop around level 8-14.",zone="The Barrens",zoneOpen=true},
    [6282]={name="Sacred Burial Trousers",quality=2,ilvl=32,reqLevel=19,sourceType="quest_reward",instructions="Reward from the quest 'Battle of Hillsbrad'. Pick it over the other reward choices. Starts with High Executor Darthalia in Undercity. Objective: Take Darthalia's Sealed Commendation to Varimathras in the Undercity.",zone="Hillsbrad Foothills",questName="Battle of Hillsbrad",lore="Because you fought with such valor and perseverance in the Battle of Hillsbrad, I have written this commendation, extolling your heroics in combat for the high command to recognize."},
    [6318]={name="Odo's Ley Staff",quality=3,ilvl=26,reqLevel=21,sourceType="boss_drop",instructions="Drops from Odo the Blindwatcher.",zone="Shadowfang Keep",npc="Odo the Blindwatcher"},
    [6321]={name="Silverlaine's Family Seal",quality=3,ilvl=26,reqLevel=21,sourceType="boss_drop",instructions="Drops from Baron Silverlaine.",zone="Shadowfang Keep",npc="Baron Silverlaine"},
    [6324]={name="Robes of Arugal",quality=3,ilvl=28,reqLevel=23,sourceType="boss_drop",instructions="Drops from Archmage Arugal.",zone="Shadowfang Keep",npc="Archmage Arugal",lore="Archmage Arugal called the worgen to Silverpine to defend against the Scourge, lost control of them immediately, and went mad in Shadowfang Keep among the things he had summoned."},
    [6332]={name="Black Pearl Ring",quality=3,ilvl=24,reqLevel=19,sourceType="rare_npc",instructions="Drops from Lady Vespira.",zone="Darkshore",npc="Lady Vespira"},
    [6340]={name="Fenrus' Hide",quality=3,ilvl=27,reqLevel=22,sourceType="boss_drop",instructions="Drops from Fenrus the Devourer.",zone="Shadowfang Keep",npc="Fenrus the Devourer"},
