    [19684]={name="Bloodvine Boots",quality=3,ilvl=65,reqLevel=60,sourceType="profession",instructions="Crafted with Tailoring (requires skill 1).",profession="Tailoring",reqSkills={{"Tailoring",300}},proc="Equip: Improves your chance to hit by 1.0%."},
    [19848]={name="Zandalar Demoniac's Wraps",quality=4,ilvl=61,reqLevel=58,sourceType="quest_reward",instructions="Reward from the quest 'Paragons of Power: The Demoniac's Wraps'.",zone="Zul'Gurub",questName="Paragons of Power: The Demoniac's Wraps",lore="Warlocks tread dangerous ground in dealing with demons, but our demoniacs take this one step further. Through an ancient and arcane ritual, they allow a demon to enter their being."},
    [19849]={name="Zandalar Demoniac's Mantle",quality=4,ilvl=61,reqLevel=58,sourceType="quest_reward",instructions="Reward from the quest 'Paragons of Power: The Demoniac's Mantle'.",zone="Zul'Gurub",questName="Paragons of Power: The Demoniac's Mantle",lore="The demoniac seeks to embody power outright, not just possess it."},
    [19876]={name="Soul Corrupter's Necklace",quality=4,ilvl=68,reqLevel=60,sourceType="boss_drop",instructions="Drops from Hakkar.",zone="Zul'Gurub",npc="Hakkar",lore="The Soulflayer, a blood god the Atal'ai priests summoned into Zul'Gurub. He feeds on the blood of his own worshippers, which is the part they had not planned for."},
    [19884]={name="Jin'do's Judgement",quality=4,ilvl=66,reqLevel=60,sourceType="boss_drop",instructions="Drops from Jin'do the Hexxer.",zone="Zul'Gurub",npc="Jin'do the Hexxer",lore="Hakkar's chief hexxer, who fights by binding pieces of his enemies' spirits and setting them loose.",proc="Equip: Improves your chance to hit by 2.0%."},
