    [19972]={name="Lucky Fishing Hat",quality=2,ilvl=40,sourceType="quest_reward",instructions="Reward from the quest 'Rare Fish - Keefer's Angelfish'. Starts with Fishbot 5000 in Stranglethorn Vale. Objective: Progress*Whir* *Click* &nbsp;I seek rare fish for Fishmaster Bluegill to catalogue. &nbsp; If you bring me a Keefer's Angelfish, I will provide you with this fine reward. *Zzzap* *Whir*.",zone="Stranglethorn Vale",questName="Rare Fish - Keefer's Angelfish",reqSkills={{"Fishing",1}}},
    [20032]={name="Flowing Ritual Robes",quality=4,ilvl=65,reqLevel=60,sourceType="boss_drop",instructions="Drops from High Priestess Mar'li.",zone="Zul'Gurub",npc="High Priestess Mar'li"},
    [20033]={name="Zandalar Demoniac's Robe",quality=4,ilvl=65,reqLevel=58,sourceType="quest_reward",instructions="Reward from the quest 'Paragons of Power: The Demoniac's Robes'.",zone="Zul'Gurub",questName="Paragons of Power: The Demoniac's Robes",lore="The ultimate symbol of power amongst the tribe is the garb we wear in battle. A demoniac's robes have fused fine runecloth and devastatingly powerful mojo into a single fabric.",proc="Equip: Improves your chance to hit by 1.0%."},
